/*
 * Standalone model-level test for CVE-2019-11479 port (tcp_min_snd_mss sysctl).
 *
 * The workspace has no kernel build toolchain (no make/bison/flex/bc and no
 * generated config headers), so a real net/ipv4 object build cannot run.
 * This harness reproduces the *exact* clamp expression introduced by the
 * candidate patch and the pre-fix expression, using the same macros/values
 * as target 3.16:
 *   - include/net/tcp.h:   #define TCP_MIN_SND_MSS 48
 *   - include/linux/kernel.h: #define max(x, y) ((x) > (y) ? (x) : (y))
 * and the target-global tunable `int sysctl_tcp_min_snd_mss`.
 *
 * It validates the arithmetic/semantic behavior of the change, not kernel
 * integration.
 */
#include <stdio.h>
#include <assert.h>

#define TCP_MIN_SND_MSS 48
#define max(x, y) ((x) > (y) ? (x) : (y))

/* Candidate patch: net/ipv4/tcp_output.c file-scope definition. */
int sysctl_tcp_min_snd_mss = TCP_MIN_SND_MSS;

/* Pre-fix target behavior (dc97a907). */
static int old_clamp(int mss_now)
{
	if (mss_now < TCP_MIN_SND_MSS)
		mss_now = TCP_MIN_SND_MSS;
	return mss_now;
}

/* Candidate behavior. */
static int new_clamp(int mss_now)
{
	mss_now = max(mss_now, sysctl_tcp_min_snd_mss);
	return mss_now;
}

int main(void)
{
	/* 1. Default compatibility: with default 48 the new clamp is identical. */
	sysctl_tcp_min_snd_mss = TCP_MIN_SND_MSS;
	assert(new_clamp(0) == 48);
	assert(old_clamp(0) == 48);
	assert(new_clamp(40) == 48);
	assert(new_clamp(48) == 48);
	assert(new_clamp(100) == 100);
	assert(new_clamp(1460) == 1460);

	/* 2. Vulnerability path: peer advertises a tiny ADVMSS -> mss_now very
	 *    small. With default config the 48 floor still preserves the old
	 *    (vulnerable-to-tiny-payload but compatible) behavior. */
	sysctl_tcp_min_snd_mss = TCP_MIN_SND_MSS;
	assert(new_clamp(-1000) == 48);
	assert(new_clamp(0) == 48);

	/* 3. Operator mitigation: raising tcp_min_snd_mss raises the floor even
	 *    when the peer advertises a tiny MSS, preventing 8-byte payloads. */
	sysctl_tcp_min_snd_mss = 536;
	assert(new_clamp(0) == 536);
	assert(new_clamp(48) == 536);
	assert(new_clamp(536) == 536);
	assert(new_clamp(1000) == 1000);
	assert(old_clamp(0) == 48);   /* old code ignores the tunable */

	/* 4. Upper bound used by the sysctl registration is 65535; value flows
	 *    through unchanged when mss_now exceeds the floor. */
	sysctl_tcp_min_snd_mss = 65535;
	assert(new_clamp(65535) == 65535);
	assert(new_clamp(65536) == 65536);

	/* 5. Restore default and re-check monotonicity. */
	sysctl_tcp_min_snd_mss = TCP_MIN_SND_MSS;
	for (int mss = -8; mss <= 2000; mss += 8)
		assert(new_clamp(mss) == old_clamp(mss));

	printf("all clamp-model assertions passed\n");
	return 0;
}

